#!/usr/bin/env bash
set -euo pipefail

export DEBIAN_FRONTEND=noninteractive

# Instala dependências básicas
apt-get update
apt-get install -y \
  ca-certificates \
  curl \
  gnupg \
  lsb-release \
  apt-transport-https

# Instala chave do Docker
install -m 0755 -d /etc/apt/keyrings
curl -fsSL https://download.docker.com/linux/debian/gpg \
  | gpg --dearmor -o /etc/apt/keyrings/docker.gpg
chmod a+r /etc/apt/keyrings/docker.gpg

# Configura repositório do Docker
cat <<EOF > /etc/apt/sources.list.d/docker.list
# Generated by TheSeed project bootstrap
# Test environment only

deb [arch="$(dpkg --print-architecture)" signed-by=/etc/apt/keyrings/docker.gpg] https://download.docker.com/linux/debian $(. /etc/os-release && echo "$VERSION_CODENAME") stable
EOF

# Instala Docker Engine + Compose
apt-get update
apt-get install -y \
  docker-ce \
  docker-ce-cli \
  containerd.io \
  docker-buildx-plugin \
  docker-compose-plugin

# Habilita e inicia serviço
systemctl enable docker
systemctl start docker

# Adiciona usuário atual ao grupo docker
if id "${USER:-vagrant}" >/dev/null 2>&1; then
  usermod -aG docker "${USER:-vagrant}"
fi

echo "Docker instalado e pronto para uso."
echo "Reinicie a sessão ou execute: newgrp docker"
